import type {
  ArgonCombatSkillRequest,
  ArgonItemSnapshot,
  ArgonSkillVisibility,
  ArgonSpellVisibility,
  ArgonTooltipDetail,
  ArgonWeaponEquipUpdate,
  ArgonWeaponSetSnapshot,
} from "../../../../types/integrations/enhancedcombathud/Argon";

const WEAPON_LIKE_TRAIT_BASE_NAMES = new Set(["weapon", "bite", "horn", "horns"]);

function assertArgonSkillSnapshot(item: ArgonItemSnapshot): asserts item is ArgonItemSnapshot & {
  advances: number;
  advanced: string;
  grouped: string;
  type: "skill";
} {
  if (
    item.type !== "skill" ||
    typeof item.advances !== "number" ||
    typeof item.advanced !== "string" ||
    typeof item.grouped !== "string"
  ) {
    throw new Error(`Argon skill snapshot ${item.id} is missing its classification fields.`);
  }
}

function assertArgonSpellSnapshot(item: ArgonItemSnapshot): asserts item is ArgonItemSnapshot & {
  lore: string;
  memorized: boolean;
  type: "spell";
} {
  if (
    item.type !== "spell" ||
    typeof item.lore !== "string" ||
    typeof item.memorized !== "boolean"
  ) {
    throw new Error(`Argon spell snapshot ${item.id} is missing its visibility fields.`);
  }
}

function assertArgonTraitSnapshot(item: ArgonItemSnapshot): asserts item is ArgonItemSnapshot & {
  disabled: boolean;
  rollable: boolean;
  traitBaseName: string;
  type: "trait";
} {
  if (
    item.type !== "trait" ||
    typeof item.disabled !== "boolean" ||
    typeof item.rollable !== "boolean" ||
    typeof item.traitBaseName !== "string"
  ) {
    throw new Error(`Argon trait snapshot ${item.id} is missing its action fields.`);
  }
}

export function normalizeArgonName(name: string): string {
  return name.trim().toLowerCase();
}

export function getArgonBaseItemName(name: string): string {
  return name.replace(/\s*\([^)]*\)\s*$/, "").trim();
}

export function isArgonWeaponLikeTrait(item: ArgonItemSnapshot): boolean {
  if (item.type !== "trait") {
    return false;
  }

  assertArgonTraitSnapshot(item);
  return (
    item.rollable &&
    !item.disabled &&
    WEAPON_LIKE_TRAIT_BASE_NAMES.has(item.traitBaseName.toLowerCase())
  );
}

export function isArgonWeaponSetItem(item: ArgonItemSnapshot): boolean {
  return item.type === "weapon" || isArgonWeaponLikeTrait(item);
}

export function isArgonEquippableWeapon(item: ArgonItemSnapshot): boolean {
  return item.type === "weapon";
}

export function isArgonAdvancedSkill(skill: ArgonItemSnapshot): boolean {
  assertArgonSkillSnapshot(skill);
  return skill.advanced === "adv" || skill.grouped === "isSpec";
}

export function isArgonTrainedSkill(skill: ArgonItemSnapshot): boolean {
  assertArgonSkillSnapshot(skill);
  return skill.advances > 0;
}

export function selectArgonSkills(
  skills: readonly ArgonItemSnapshot[],
  visibility: ArgonSkillVisibility,
): string[] {
  skills.forEach(assertArgonSkillSnapshot);

  if (visibility === "basic") {
    return skills.filter((skill) => !isArgonAdvancedSkill(skill)).map((skill) => skill.id);
  }

  if (visibility === "advanced") {
    return skills.filter(isArgonAdvancedSkill).map((skill) => skill.id);
  }

  if (visibility === "trained") {
    return skills.filter(isArgonTrainedSkill).map((skill) => skill.id);
  }

  return skills.map((skill) => skill.id);
}

export function selectArgonSpells(
  spells: readonly ArgonItemSnapshot[],
  visibility: ArgonSpellVisibility,
): string[] {
  spells.forEach(assertArgonSpellSnapshot);

  const selected =
    visibility === "memorized"
      ? spells.filter((spell) => spell.lore === "petty" || spell.memorized)
      : spells;
  return selected.map((spell) => spell.id);
}

export function selectArgonWeaponActions(items: readonly ArgonItemSnapshot[]): string[] {
  return items
    .filter((item) => item.type === "weapon" || isArgonWeaponLikeTrait(item))
    .map((item) => item.id);
}

export function selectArgonTraitActions(items: readonly ArgonItemSnapshot[]): string[] {
  return items
    .filter((item) => {
      if (item.type !== "trait") {
        return false;
      }

      assertArgonTraitSnapshot(item);
      return item.rollable && !item.disabled;
    })
    .map((item) => item.id);
}

export function selectArgonCombatSkills(
  skills: readonly ArgonItemSnapshot[],
  requests: readonly ArgonCombatSkillRequest[],
): string[] {
  skills.forEach(assertArgonSkillSnapshot);

  return requests.flatMap((request) => {
    const normalizedName = normalizeArgonName(request.name);
    const skill = skills.find((candidate) => normalizeArgonName(candidate.name) === normalizedName);

    if (!skill || (request.trained && !isArgonTrainedSkill(skill))) {
      return [];
    }

    return [skill.id];
  });
}

export function parseArgonCombatItemPatterns(value: string): string[] {
  return value
    .split(/[\n,;]+/)
    .map((pattern) => pattern.trim())
    .filter(Boolean);
}

export function argonWildcardMatch(value: string, pattern: string): boolean {
  const escapedPattern = pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*");
  return new RegExp(`^${escapedPattern}$`, "i").test(value);
}

export function selectArgonCombatItems(
  items: readonly ArgonItemSnapshot[],
  patterns: readonly string[],
): string[] {
  if (!patterns.length) {
    return [];
  }

  return items
    .filter(
      (item) =>
        !["skill", "weapon", "trait", "spell", "prayer"].includes(item.type) &&
        (item.quantity === null || item.quantity > 0) &&
        patterns.some((pattern) => argonWildcardMatch(item.name, pattern)),
    )
    .map((item) => item.id);
}

export function getArgonItemDetails(item: ArgonItemSnapshot): ArgonTooltipDetail[] {
  const details: ArgonTooltipDetail[] = [];

  if (item.type === "weapon" || isArgonWeaponLikeTrait(item)) {
    details.push(
      { label: "wfrp4e-compatibility-box.Argon.Tooltip.Damage", value: item.damage },
      {
        label: "wfrp4e-compatibility-box.Argon.Tooltip.Range",
        value: item.range ?? item.reach,
      },
    );
  }

  if (item.type === "skill") {
    details.push({
      label: "wfrp4e-compatibility-box.Argon.Tooltip.Total",
      value: item.total,
    });
  }

  if (item.type === "spell") {
    details.push(
      {
        label: "wfrp4e-compatibility-box.Argon.Tooltip.CastingNumber",
        value: item.castingNumber,
      },
      { label: "wfrp4e-compatibility-box.Argon.Tooltip.Range", value: item.range },
      { label: "wfrp4e-compatibility-box.Argon.Tooltip.Target", value: item.target },
      { label: "wfrp4e-compatibility-box.Argon.Tooltip.Duration", value: item.duration },
    );
  }

  if (item.type === "prayer") {
    details.push(
      { label: "wfrp4e-compatibility-box.Argon.Tooltip.Range", value: item.range },
      { label: "wfrp4e-compatibility-box.Argon.Tooltip.Target", value: item.target },
      { label: "wfrp4e-compatibility-box.Argon.Tooltip.Duration", value: item.duration },
    );
  }

  return details.filter((detail) => detail.value !== undefined && detail.value !== "");
}

export function deriveArgonWeaponEquipUpdates(
  sets: readonly ArgonWeaponSetSnapshot[],
  activeSetId: string,
): ArgonWeaponEquipUpdate[] {
  const activeSet = sets.find((set) => set.id === activeSetId);

  if (!activeSet) {
    throw new Error(`Argon weapon set ${activeSetId} does not exist.`);
  }

  const activeItems = new Map(activeSet.items.map((item) => [item.id, item]));
  const inactiveItems = new Map(
    sets
      .filter((set) => set.id !== activeSetId)
      .flatMap((set) => set.items)
      .filter((item) => !activeItems.has(item.id))
      .map((item) => [item.id, item]),
  );

  return [
    ...Array.from(activeItems.values(), (item) =>
      item.equipped ? [] : [{ "_id": item.id, "system.equipped.value": true }],
    ).flat(),
    ...Array.from(inactiveItems.values(), (item) =>
      item.equipped ? [{ "_id": item.id, "system.equipped.value": false }] : [],
    ).flat(),
  ];
}
