import { MODULE_ID } from "../../../constants";
import { notifyError } from "../../notifications/notify-user";
import { configureSplatter } from "./configure-splatter";

const LOCALIZATION_ROOT = `${MODULE_ID}.Splatter.Configuration`;

function localize(key: string): string {
  return game?.i18n.localize(`${LOCALIZATION_ROOT}.${key}`) ?? key;
}

export class SplatterConfigurationMenu extends foundry.applications.api.ApplicationV2 {
  override async render(_force?: boolean): Promise<this> {
    try {
      await configureSplatter();
      ui?.notifications?.info(localize("Success"));
    } catch (error) {
      notifyError(localize("Error"), error);
    }

    return this;
  }
}
