import {
  criticalCapacity,
  healthPercent,
  matchesWfrpConfiguration,
} from "../../../functions/integrations/bossbar/health";
import { MODULE_ID } from "../../../constants";
import { BOSS_BAR_MODULE_ID, BOSS_BAR_SETTINGS } from "./constants";
import { updateCriticalSegments } from "./critical-segments";
import {
  localizeBossBar,
  readBossBarConfiguration,
  reportBossBarError,
  usesUpInArms,
} from "./configuration";
import { getBossBarApplication, getBossHealth, type BossBarApplication } from "./runtime";
import { createWoundsBar, getWoundsStyle } from "./wounds-bar";

export function refreshBossBarDisplay(application = getBossBarApplication()): void {
  if (!application?.element || application.id !== "boss-bar") return;
  const root = application.element;
  root.classList.add("wfrp4e-compatibility-box-bossbar");
  const stacked =
    usesUpInArms() &&
    game?.settings.get(MODULE_ID, BOSS_BAR_SETTINGS.stacked) === true &&
    matchesWfrpConfiguration(readBossBarConfiguration());
  const styles = game?.settings.get(BOSS_BAR_MODULE_ID, "barStyles") as Parameters<
    typeof getWoundsStyle
  >[0];
  const styleId = game?.settings.get(MODULE_ID, BOSS_BAR_SETTINGS.woundsStyle);
  const style = getWoundsStyle(styles, styleId);

  for (const row of root.querySelectorAll<HTMLElement>(".bar-list-item")) {
    const actor = application.bars.find((bar) => bar.actor.uuid === row.dataset["uuid"])?.actor;
    if (!actor) continue;
    const primary = row.querySelector<HTMLElement>(".boss-bar-container:not(.wfrp-bossbar-wounds)");
    if (!primary) continue;
    if (!stacked || !style) {
      updateCriticalSegments(primary);
      row.querySelectorAll("[data-wfrp-bossbar-extra]").forEach((element) => element.remove());
      if (primary.dataset["wfrpBossbarPrimary"]) {
        primary.style.removeProperty("--bar-percent");
        primary.removeAttribute("role");
        primary.removeAttribute("aria-label");
        primary.removeAttribute("aria-valuenow");
        primary.removeAttribute("aria-valuemax");
        primary.removeAttribute("aria-valuemin");
        delete primary.dataset["wfrpBossbarPrimary"];
      }
      continue;
    }
    const health = getBossHealth(actor);
    const capacity = criticalCapacity(health);
    updateCriticalSegments(primary, capacity.max);
    primary.dataset["wfrpBossbarPrimary"] = "true";
    primary.style.setProperty(
      "--bar-percent",
      `${healthPercent(capacity.remaining, capacity.max)}%`,
    );
    setAccessibleHealth(
      primary,
      localizeBossBar("CriticalCapacity"),
      capacity.remaining,
      capacity.max,
    );

    let wounds = row.querySelector<HTMLElement>(".wfrp-bossbar-wounds");
    if (wounds?.dataset["style"] !== style.id) {
      row.querySelectorAll("[data-wfrp-bossbar-extra]").forEach((element) => element.remove());
      wounds = createWoundsBar(row.ownerDocument, style);
      wounds.dataset["wfrpBossbarExtra"] = "";
      wounds.dataset["style"] = style.id;
      primary.before(wounds);
    }
    if (wounds) {
      wounds.style.setProperty(
        "--bar-percent",
        `${healthPercent(health.wounds, health.maxWounds)}%`,
      );
      wounds.classList.toggle("wfrp-bossbar-threat", health.wounds <= 0);
      setAccessibleHealth(
        wounds,
        localizeBossBar("Wounds"),
        Math.max(0, health.wounds),
        health.maxWounds,
      );
    }
  }
}

function setAccessibleHealth(
  element: HTMLElement,
  label: string,
  value: number,
  max: number,
): void {
  element.setAttribute("role", "progressbar");
  element.setAttribute("aria-label", label);
  element.setAttribute("aria-valuemin", "0");
  element.setAttribute("aria-valuemax", String(Math.max(0, max)));
  element.setAttribute("aria-valuenow", String(Math.min(value, Math.max(0, max))));
}

let refreshQueued = false;

export function queueBossBarRefresh(): void {
  if (refreshQueued) return;
  refreshQueued = true;
  queueMicrotask(() => {
    refreshQueued = false;
    const application: BossBarApplication | undefined = getBossBarApplication();
    if (!application?.element?.isConnected) return;
    try {
      application.updateBars();
      refreshBossBarDisplay(application);
    } catch (error) {
      reportBossBarError(error);
    }
  });
}
