import { selectBosses } from "../../../functions/integrations/bossbar/selection";
import { MODULE_ID } from "../../../constants";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { BOSS_BAR_MODULE_ID, BOSS_BAR_SETTINGS } from "./constants";
import { getBossCandidates, type BossCombat } from "./runtime";

const pendingCombats = new WeakSet<BossCombat>();

export async function showCombatBosses(combat: BossCombat): Promise<void> {
  if (
    !game?.user?.isGM ||
    !isOptionalFeatureEnabled("bossBar") ||
    !game.settings.get(MODULE_ID, BOSS_BAR_SETTINGS.automatic) ||
    !combat.scene ||
    pendingCombats.has(combat)
  )
    return;

  const bosses = selectBosses(getBossCandidates(combat));
  const existing = combat.scene.getFlag(BOSS_BAR_MODULE_ID, "actors") ?? [];
  const known = new Set(existing.map((entry) => entry.uuid));
  const styles = game.settings.get(BOSS_BAR_MODULE_ID, "barStyles") as { id: string }[];
  const additions = bosses
    .filter((boss) => {
      if (known.has(boss.uuid)) return false;
      known.add(boss.uuid);
      return true;
    })
    .map((boss) => ({ uuid: boss.uuid, style: styles[0]?.id ?? "default", hideName: false }));
  if (!additions.length) return;

  pendingCombats.add(combat);
  try {
    await combat.scene.setFlag(BOSS_BAR_MODULE_ID, "actors", [...existing, ...additions]);
  } finally {
    pendingCombats.delete(combat);
  }
}
