import type { EmptyFolderNode } from "../../../types/folders/EmptyFolders";

/** Return empty branches in deletion order. Cycles and occupied branches are retained. */
export function planEmptyFolders(
  folders: EmptyFolderNode[],
  occupied: ReadonlySet<string>,
): EmptyFolderNode[] {
  const remaining = new Set(folders.map((folder) => folder.id));
  const result: EmptyFolderNode[] = [];
  while (remaining.size) {
    const parents = new Set(
      folders.filter((folder) => remaining.has(folder.id)).map((folder) => folder.parent),
    );
    const leaves = folders.filter(
      (folder) => remaining.has(folder.id) && !occupied.has(folder.id) && !parents.has(folder.id),
    );
    if (!leaves.length) break;
    for (const folder of leaves) {
      result.push(folder);
      remaining.delete(folder.id);
    }
  }
  return result;
}
