import { registerPaperDollHooks } from "../../patches/paper-doll/register-paper-doll-hooks";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { isModuleActive } from "../is-module-active";

export const PAPER_DOLL_MODULE_ID = "fvtt-paper-doll-ui";

export function registerPaperDollIntegration(): void {
  if (!isModuleActive(PAPER_DOLL_MODULE_ID)) {
    return;
  }

  if (!isOptionalFeatureEnabled("paperDoll")) {
    return;
  }

  registerPaperDollHooks();
}
