export function repairWfrpRollModes(): boolean {
  const wfrpConfig = game?.wfrp4e?.config;
  const chatMessageModes = CONFIG.ChatMessage.modes;

  if (!wfrpConfig || !chatMessageModes) {
    return false;
  }

  // Warhammer Library recursively localizes the WFRP config in place. Keep that operation away
  // from Foundry's CONFIG object as well as the deprecated CONFIG.Dice.rollModes compatibility
  // proxy retained by WFRP4e 9.x.
  wfrpConfig.rollModes = foundry.utils.deepClone(chatMessageModes);
  return true;
}
