import type {
  ArgonWeaponSetFlags,
  PaperDollMainHandSlots,
  PaperDollWeaponSetBridgeInput,
} from "../../../../types/integrations/paper-doll-argon/Bridge";
import type { PaperDollSlotState } from "../../../../types/patches/paper-doll/Equipment";

const PAPER_DOLL_QUICK_SLOT_IDS = ["TRINKET", "WRIST_RIGHT"] as const;

function compareSlotIndexes(a: string, b: string): number {
  const aNumber = Number(a);
  const bNumber = Number(b);

  if (Number.isInteger(aNumber) && Number.isInteger(bNumber)) {
    return aNumber - bNumber;
  }

  return a.localeCompare(b);
}

export function selectPaperDollQuickItemUuids(state: PaperDollSlotState): string[] {
  const selected = new Set<string>();

  for (const slotId of PAPER_DOLL_QUICK_SLOT_IDS) {
    const entries = state[slotId] ?? {};

    for (const index of Object.keys(entries).sort(compareSlotIndexes)) {
      const uuid = entries[index];

      if (uuid) {
        selected.add(uuid);
      }
    }
  }

  return [...selected];
}

export function getPaperDollMainHandSlots(state: PaperDollSlotState): PaperDollMainHandSlots {
  return {
    left: state["MAIN_LEFT"]?.["0"] ?? null,
    right: state["MAIN_RIGHT"]?.["0"] ?? null,
  };
}

export function deriveArgonWeaponSetsFromPaperDoll({
  activeSetId,
  mainHand,
  mainSlots,
  weaponSets,
}: PaperDollWeaponSetBridgeInput): ArgonWeaponSetFlags {
  const primary = mainHand === "l" ? mainSlots.left : mainSlots.right;
  const offhand = mainHand === "l" ? mainSlots.right : mainSlots.left;
  const secondary = offhand === primary ? null : offhand;

  return {
    ...weaponSets,
    [activeSetId]: {
      ...weaponSets[activeSetId],
      primary,
      secondary,
    },
  };
}

export function haveSameArgonWeaponSets(a: ArgonWeaponSetFlags, b: ArgonWeaponSetFlags): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}
