import { getChatCardActorReferences } from "../../../functions/patches/wfrp4e/chat-card-references";
import type {
  ChatActorReference,
  ChatCardDocument,
  ChatRenderOptions,
} from "../../../../types/patches/wfrp4e/ChatCard";
import { chatCardText, chatCardTextElement } from "./chat-card-text";

const repairedPrototypes = new WeakSet<ChatCardDocument>();

function hasActor(reference: ChatActorReference): boolean {
  if (!game) return false;
  switch (reference.kind) {
    case "speaker":
      // A token speaker identifies a particular actor instance. Do not substitute the base
      // actor for a deleted synthetic actor, even if that base actor still exists.
      if (reference.scene && reference.token) {
        return Boolean(game.scenes.get(reference.scene)?.tokens.get(reference.token)?.actor);
      }
      return Boolean(reference.actor && game.actors.get(reference.actor));
    case "uuid":
      return Boolean(reference.uuid && fromUuidSync(reference.uuid)?.documentName === "Actor");
    case "message": {
      const message = game.messages.get(reference.id);
      if (!message) return !reference.required;
      if (message._source.type !== "test") return false;
      return getChatCardActorReferences(message._source).every(hasActor);
    }
  }
}

async function renderTextCard(
  message: ChatCardDocument,
  options?: ChatRenderOptions,
): Promise<HTMLElement> {
  const source = message.toObject();
  const contentVisible = message.visible && message.isContentVisible;
  const text = contentVisible ? chatCardText(source.content) : "";

  // Use an unsaved core document so render hooks never receive the broken WFRP model.
  // Retain identity, author, timestamp, rolls and visibility fields for the normal chat shell.
  const plainMessage = new foundry.documents.ChatMessage({
    ...source,
    type: "base",
    system: {},
    flags: {},
    content: chatCardTextElement(text).outerHTML,
  });
  const html = await plainMessage.renderHTML(options);
  const content = html.querySelector<HTMLElement>(".message-content");
  if (content) {
    // Remove any controls or enrichment added by other render hooks. For hidden content,
    // preserve only the core renderer's placeholder, never the stored result.
    const renderedText =
      contentVisible && plainMessage.isContentVisible ? text : chatCardText(content.innerHTML);
    content.replaceChildren(chatCardTextElement(renderedText));
  }
  // WFRP's delegated right-click menu reconstructs tests from the original stored message.
  // Stop it for this text-only card; keep the native text-copy menu and core header buttons.
  html.addEventListener("contextmenu", (event) => event.stopPropagation(), { capture: true });
  return html;
}

export function repairOrphanedChatCards(): boolean {
  const prototype = CONFIG.ChatMessage.documentClass?.prototype;
  if (!prototype || repairedPrototypes.has(prototype)) return false;
  const originalRender = prototype.renderHTML;
  prototype.renderHTML = function (this: ChatCardDocument, options?: ChatRenderOptions) {
    const references = getChatCardActorReferences(this._source);
    if (references.some((reference) => !hasActor(reference))) {
      return renderTextCard(this, options);
    }
    return originalRender.call(this, options);
  };
  repairedPrototypes.add(prototype);
  return true;
}
