import {
  matchesWfrpConfiguration,
  WFRP_BOSS_BAR_CONFIGURATION,
} from "../../../functions/integrations/bossbar/health";
import type { BossBarConfiguration } from "../../../../types/integrations/bossbar/BossBar";
import { MODULE_ID } from "../../../constants";
import { promptCompatibilitySetup } from "../../settings/compatibility-prompts";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { BOSS_BAR_MODULE_ID, BOSS_BAR_SETTINGS } from "./constants";

export function localizeBossBar(key: string): string {
  return game?.i18n.localize(`${MODULE_ID}.BossBar.${key}`) ?? key;
}

export function reportBossBarError(error: unknown): void {
  console.error(`${MODULE_ID} | Boss Bar integration failed.`, error);
  ui?.notifications?.error(localizeBossBar("Error"));
}

export function readBossBarConfiguration(): BossBarConfiguration {
  return {
    currentHpPath: game?.settings.get(BOSS_BAR_MODULE_ID, "currentHpPath") as string,
    maxHpPath: game?.settings.get(BOSS_BAR_MODULE_ID, "maxHpPath") as string,
    woundsSystem: game?.settings.get(BOSS_BAR_MODULE_ID, "woundsSystem") as boolean,
  };
}

export function usesUpInArms(): boolean {
  return game?.settings.get("wfrp4e", "uiaCrits") === true;
}

function upInArmsDefaultStyles(): { id: string }[] | undefined {
  if (!usesUpInArms()) return;
  const styles = game?.settings.get(BOSS_BAR_MODULE_ID, "barStyles") as { id: string }[];
  const segmented = styles.find((style) => style.id === "segmented");
  if (!segmented || styles[0] === segmented) return;
  // Boss Bar uses its first theme for newly added actors. Existing selections keep their theme IDs.
  return [segmented, ...styles.filter((style) => style !== segmented)];
}

export async function configureBossBar(): Promise<BossBarConfiguration> {
  if (!game?.ready || !game.user?.isGM || !isOptionalFeatureEnabled("bossBar")) {
    throw new Error("An active Boss Bar integration and a ready GM session are required.");
  }
  for (const key of Object.keys(WFRP_BOSS_BAR_CONFIGURATION)) {
    if (!game.settings.settings?.has(`${BOSS_BAR_MODULE_ID}.${key}`)) {
      throw new Error(`Boss Bar setting ${key} is unavailable.`);
    }
  }
  for (const [key, value] of Object.entries(WFRP_BOSS_BAR_CONFIGURATION)) {
    await game.settings.set(BOSS_BAR_MODULE_ID, key, value);
  }
  await game.settings.set(MODULE_ID, BOSS_BAR_SETTINGS.stacked, true);
  const styles = upInArmsDefaultStyles();
  if (styles) await game.settings.set(BOSS_BAR_MODULE_ID, "barStyles", styles);
  ui?.notifications?.info(localizeBossBar("Configured"));
  return { ...WFRP_BOSS_BAR_CONFIGURATION };
}

export function promptBossBarSetup(): Promise<void> {
  return promptCompatibilitySetup({
    ignoreSetting: BOSS_BAR_SETTINGS.ignorePrompt,
    isEnabled: () => isOptionalFeatureEnabled("bossBar"),
    matches: () =>
      matchesWfrpConfiguration(readBossBarConfiguration()) &&
      game?.settings.get(MODULE_ID, BOSS_BAR_SETTINGS.stacked) === true &&
      !upInArmsDefaultStyles(),
    title: () => localizeBossBar("SetupTitle"),
    content: () =>
      `<p>${localizeBossBar("SetupDescription")}</p><p>${localizeBossBar(usesUpInArms() ? "SetupUpInArms" : "SetupCore")}</p><p>${localizeBossBar("SetupCustomization")}</p>`,
    configure: configureBossBar,
  });
}
