// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- This boundary adapts dynamic WFRP4e documents whose contracts are not published.
// @ts-nocheck -- Raw Foundry/WFRP4e access is intentionally confined to these snapshot adapters.

import {
  getArgonBaseItemName,
  getArgonItemDetails,
  isArgonEquippableWeapon,
  isArgonTrainedSkill,
  isArgonWeaponLikeTrait,
  isArgonWeaponSetItem,
  parseArgonCombatItemPatterns,
  selectArgonCombatItems,
  selectArgonCombatSkills,
  selectArgonSkills,
  selectArgonSpells,
  selectArgonTraitActions,
  selectArgonWeaponActions,
} from "../../../functions/integrations/enhancedcombathud/argon-logic";
import { MODULE_ID } from "../../../constants";
import {
  ARGON_COMBAT_ITEM_PATTERNS_SETTING,
  DEFAULT_ARGON_COMBAT_ITEM_PATTERNS,
} from "../../settings/register-module-settings";
import { getArgonActorFlag } from "./actor-flags";
import { ARGON_ACTOR_FLAG_SCOPE, COMBAT_CHARACTERISTICS, COMBAT_SKILLS } from "./constants";

function requireRecord(value, context) {
  if (typeof value !== "object" || value === null) {
    throw new Error(`${MODULE_ID} | ${context} must be an object.`);
  }

  return value;
}

function requireString(value, context) {
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`${MODULE_ID} | ${context} must be a non-empty string.`);
  }

  return value;
}

function requireBoolean(value, context) {
  if (typeof value !== "boolean") {
    throw new Error(`${MODULE_ID} | ${context} must be a boolean.`);
  }

  return value;
}

function requireNumber(value, context) {
  if (!Number.isNumeric(value)) {
    throw new Error(`${MODULE_ID} | ${context} must be numeric.`);
  }

  return Number(value);
}

function getOptionalNumericValue(value) {
  if (value === undefined || value === null || value === "") return null;
  return requireNumber(value, "item quantity");
}

function getVisibilityFlag(actor, flag, allowedValues, defaultValue) {
  const value = getArgonActorFlag(actor, flag);

  if (value === undefined) {
    return defaultValue;
  }

  if (!allowedValues.includes(value)) {
    throw new Error(
      `${MODULE_ID} | Argon actor flag ${ARGON_ACTOR_FLAG_SCOPE}.${flag} has invalid value ${String(value)}.`,
    );
  }

  return value;
}

function addArgonItemDetailFields(snapshot, source, type) {
  if (type === "weapon" || type === "trait") {
    snapshot.damage = source.DamageString;
    snapshot.range = requireBoolean(source.isRanged, `${type} ${snapshot.name} ranged state`)
      ? source.Range
      : undefined;
    snapshot.reach = source.Reach;
  }

  if (type === "skill") {
    snapshot.total = source.total?.value;
  }

  if (type === "spell") {
    snapshot.castingNumber = source.cn?.value;
  }

  if (type === "spell" || type === "prayer") {
    snapshot.duration = source.Duration;
    snapshot.range = source.Range;
    snapshot.target = source.Target;
  }
}

function toArgonItemSnapshot(item, includeDetails = false) {
  const source = requireRecord(item, "Argon item");
  const type = requireString(source.type, "Argon item type");
  const name = requireString(source.name, `${type} item name`);
  const id = requireString(source.id, `${type} ${name} id`);
  const quantity = source.quantity?.value ?? source.system?.quantity?.value;
  const snapshot = {
    id,
    name,
    quantity: getOptionalNumericValue(quantity),
    type,
  };

  if (type === "skill") {
    snapshot.advanced = requireString(source.advanced?.value, `${name} advanced classification`);
    snapshot.grouped = requireString(source.grouped?.value, `${name} grouped classification`);
    snapshot.advances = requireNumber(
      source.advances?.value ?? source.system?.advances?.value,
      `${name} advances`,
    );
  }

  if (type === "spell") {
    snapshot.lore = requireString(source.lore?.value, `${name} lore`);
    snapshot.memorized = requireBoolean(source.memorized?.value, `${name} memorized state`);
  }

  if (type === "trait") {
    snapshot.disabled = requireBoolean(source.system?.disabled, `${name} disabled state`);
    snapshot.rollable = requireBoolean(source.rollable?.value, `${name} rollable state`);
    snapshot.traitBaseName = getArgonBaseItemName(name);
  }

  if (includeDetails) {
    addArgonItemDetailFields(snapshot, source, type);
  }

  return snapshot;
}

function toArgonItemSnapshots(items) {
  return [...items].map((item) => toArgonItemSnapshot(item));
}

function resolveSelectedItems(items, selectedIds) {
  const itemById = new Map([...items].map((item) => [item.id, item]));

  return selectedIds.map((id) => {
    const item = itemById.get(id);

    if (!item) {
      throw new Error(`${MODULE_ID} | Selected Argon item ${id} is no longer available.`);
    }

    return item;
  });
}

export function getItemDetails(item) {
  return getArgonItemDetails(toArgonItemSnapshot(item, true));
}

export function getConfiguredSkills(actor) {
  const visibility = getVisibilityFlag(
    actor,
    "skillVisibility",
    ["all", "basic", "advanced", "trained"],
    "all",
  );
  const skills = [...actor.itemTypes.skill];
  return resolveSelectedItems(skills, selectArgonSkills(toArgonItemSnapshots(skills), visibility));
}

export function getConfiguredSpells(actor) {
  const visibility = getVisibilityFlag(actor, "spellVisibility", ["all", "memorized"], "all");
  const spells = [...actor.itemTypes.spell];
  return resolveSelectedItems(spells, selectArgonSpells(toArgonItemSnapshots(spells), visibility));
}

export function getWeaponActionItems(actor) {
  const items = [...actor.itemTypes.weapon, ...actor.itemTypes.trait];
  return resolveSelectedItems(items, selectArgonWeaponActions(toArgonItemSnapshots(items)));
}

export function getTraitActionItems(actor) {
  const traits = [...actor.itemTypes.trait];
  return resolveSelectedItems(traits, selectArgonTraitActions(toArgonItemSnapshots(traits)));
}

export function getCombatSkillActions(actor) {
  const actions = COMBAT_CHARACTERISTICS.map((action) => ({
    ...action,
    type: "characteristic",
  }));
  const requests = COMBAT_SKILLS.map((config) => ({
    name: getCombatSkillName(config),
    trained: Boolean(config.trained),
  }));
  const actorSkills = [...actor.itemTypes.skill];
  const skills = resolveSelectedItems(
    actorSkills,
    selectArgonCombatSkills(toArgonItemSnapshots(actorSkills), requests),
  );

  return [
    ...actions,
    ...skills.map((item) => ({
      item,
      type: "skill",
    })),
  ];
}

function getCombatSkillName({ nameKey, fallback, specKey, specFallback }) {
  const name = localizeFallback(`NAME.${nameKey}`, fallback);
  if (!specKey) return name;

  return `${name} (${localizeFallback(specKey, specFallback)})`;
}

export function getCombatItems(actor) {
  const configuredValue =
    game.settings.get(MODULE_ID, ARGON_COMBAT_ITEM_PATTERNS_SETTING) ??
    DEFAULT_ARGON_COMBAT_ITEM_PATTERNS;
  const patterns = parseArgonCombatItemPatterns(String(configuredValue));
  const items = [...actor.items];
  return resolveSelectedItems(items, selectArgonCombatItems(toArgonItemSnapshots(items), patterns));
}

export function getItemQuantity(item) {
  return Number(item?.quantity?.value ?? item?.system?.quantity?.value);
}

export function isWeaponSetItem(item) {
  return isArgonWeaponSetItem(toArgonItemSnapshot(item));
}

export function isEquippableWeapon(item) {
  return isArgonEquippableWeapon(toArgonItemSnapshot(item));
}

export function isWeaponLikeTrait(item) {
  return isArgonWeaponLikeTrait(toArgonItemSnapshot(item));
}

export function isTrainedSkill(skill) {
  return isArgonTrainedSkill(toArgonItemSnapshot(skill));
}

function localizeFallback(key, fallback) {
  const localized = game.i18n.localize(key);
  return localized === key ? fallback : localized;
}
