import { notifyError } from "../notifications/notify-user";
import { removeEmptyFolders, scanEmptyFolders } from "./empty";

const TITLE = "Purge Empty Folders";

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

export async function purgeEmptyFolders(): Promise<void> {
  if (!game?.ready || !game.user?.isGM) {
    ui?.notifications?.warn("Only a GM in a loaded world can purge empty folders.");
    return;
  }
  try {
    const scope = await foundry.applications.api.DialogV2.wait({
      window: { title: TITLE },
      content:
        "<p>Search for empty folders in world directories, compendiums, or both. Compendium cleanup includes the sidebar and folders inside unlocked packs. Locked packs are skipped.</p><p>All empty folders in the selected scope qualify, including non-WFRP folders. You will review the list before deletion.</p>",
      buttons: [
        { action: "world", label: "World folders" },
        { action: "compendiums", label: "Compendium folders" },
        { action: "both", label: "Both" },
        { action: "cancel", label: "Cancel", default: true },
      ],
      rejectClose: false,
    });
    if (scope !== "world" && scope !== "compendiums" && scope !== "both") return;
    const scan = await scanEmptyFolders(scope);
    const skipped = scan.skippedPacks ? ` Skipped ${scan.skippedPacks} locked packs.` : "";
    if (!scan.candidates.length) {
      ui?.notifications?.info(`No empty folders found.${skipped}`);
      return;
    }
    const entries = scan.candidates
      .map(({ group, name }) => `<li>${escapeHtml(group.label)}: ${escapeHtml(name)}</li>`)
      .join("");
    const choice = await foundry.applications.api.DialogV2.wait({
      window: { title: TITLE },
      position: { width: 600 },
      content: `<p>Remove ${scan.candidates.length} empty folders, including parents left empty after their children are removed?${skipped}</p><p>Folders are rechecked before deletion. Documents and compendium packs are never deleted.</p><details><summary>Review folders</summary><ul>${entries}</ul></details>`,
      buttons: [
        { action: "purge", label: "Purge Empty Folders" },
        { action: "cancel", label: "Cancel", default: true },
      ],
      rejectClose: false,
    });
    if (choice !== "purge") return;
    const result = await removeEmptyFolders(scan);
    ui?.notifications?.info(
      `Removed ${result.deleted} empty folders. Skipped ${result.skipped} folders that changed.${skipped}`,
    );
  } catch (error) {
    notifyError(
      `${TITLE} stopped. Some folders may already have been removed. See the console for details.`,
      error,
    );
  }
}
