import { MODULE_ID } from "../../../constants";

const PAPER_DOLL_SLOT_SELECTOR = ".paper-doll .paper-doll-slot";
const DRAG_TOOLTIP_ATTRIBUTE = `data-${MODULE_ID}-drag-tooltip`;
const MANAGED_TOOLTIP_ATTRIBUTE = `data-${MODULE_ID}-tooltip`;
const ORIGINAL_TOOLTIP_ATTRIBUTE = `data-${MODULE_ID}-original-tooltip`;

interface SlotTooltip {
  fallback: string;
  key: string;
}

const SLOT_TOOLTIPS: Readonly<Record<string, SlotTooltip>> = {
  HEAD: { key: `${MODULE_ID}.SlotTooltip.Head`, fallback: "Head armour" },
  CAPE: { key: `${MODULE_ID}.SlotTooltip.Cape`, fallback: "Aesthetic Item" },
  BODY: { key: `${MODULE_ID}.SlotTooltip.Body`, fallback: "Body armour" },
  GLOVES: { key: `${MODULE_ID}.SlotTooltip.Gloves`, fallback: "Arm armour" },
  BOOTS: { key: `${MODULE_ID}.SlotTooltip.Boots`, fallback: "Leg armour" },
  TRINKET: { key: `${MODULE_ID}.SlotTooltip.Trinket`, fallback: "Ready Item" },
  PENDANT: { key: `${MODULE_ID}.SlotTooltip.Pendant`, fallback: "Amulet" },
  RING: { key: `${MODULE_ID}.SlotTooltip.Ring`, fallback: "Worn Item" },
  WRIST_LEFT: { key: `${MODULE_ID}.SlotTooltip.WristLeft`, fallback: "Light Source" },
  WRIST_RIGHT: { key: `${MODULE_ID}.SlotTooltip.WristRight`, fallback: "Quick Use Item" },
  MAIN_LEFT: { key: `${MODULE_ID}.SlotTooltip.MainLeft`, fallback: "Main hand" },
  MAIN_RIGHT: { key: `${MODULE_ID}.SlotTooltip.MainRight`, fallback: "Off hand" },
};

let dragInProgress = false;

function findPaperDollSlot(target: EventTarget | null): HTMLElement | null {
  if (!(target instanceof Element)) {
    return null;
  }

  const slot = target.closest<HTMLElement>(PAPER_DOLL_SLOT_SELECTOR);
  return slot?.closest(".paper-doll") ? slot : null;
}

function clearManagedTooltips(): void {
  document.querySelectorAll<HTMLElement>(`[${MANAGED_TOOLTIP_ATTRIBUTE}]`).forEach((slot) => {
    const originalTooltip = slot.getAttribute(ORIGINAL_TOOLTIP_ATTRIBUTE);

    if (originalTooltip) {
      slot.dataset["tooltip"] = originalTooltip;
    } else {
      slot.removeAttribute("data-tooltip");
    }

    slot.removeAttribute(MANAGED_TOOLTIP_ATTRIBUTE);
    slot.removeAttribute(ORIGINAL_TOOLTIP_ATTRIBUTE);
  });
}

function hideSlotTooltipsDuringDrag(): void {
  document.querySelectorAll<HTMLElement>(PAPER_DOLL_SLOT_SELECTOR).forEach((slot) => {
    const tooltip = slot.getAttribute("data-tooltip");

    if (!tooltip) {
      return;
    }

    slot.setAttribute(DRAG_TOOLTIP_ATTRIBUTE, tooltip);
    slot.removeAttribute("data-tooltip");
  });
}

function restoreSlotTooltipsAfterDrag(): void {
  document.querySelectorAll<HTMLElement>(`[${DRAG_TOOLTIP_ATTRIBUTE}]`).forEach((slot) => {
    const tooltip = slot.getAttribute(DRAG_TOOLTIP_ATTRIBUTE);

    if (tooltip) {
      slot.dataset["tooltip"] = tooltip;
    }

    slot.removeAttribute(DRAG_TOOLTIP_ATTRIBUTE);
  });
}

function applyTooltip(slot: HTMLElement): void {
  if (dragInProgress || slot.hasAttribute(MANAGED_TOOLTIP_ATTRIBUTE)) {
    return;
  }

  const tooltip = SLOT_TOOLTIPS[slot.dataset["id"] ?? ""];

  if (!tooltip || !game) {
    return;
  }

  const translatedTooltip = game.i18n.localize(tooltip.key);
  const roleTooltip = translatedTooltip === tooltip.key ? tooltip.fallback : translatedTooltip;
  const itemTooltip = slot.dataset["tooltip"];

  if (itemTooltip) {
    slot.setAttribute(ORIGINAL_TOOLTIP_ATTRIBUTE, itemTooltip);
  }

  slot.dataset["tooltip"] = itemTooltip ? `${roleTooltip}: ${itemTooltip}` : roleTooltip;
  slot.setAttribute(MANAGED_TOOLTIP_ATTRIBUTE, "");
}

function handlePointerOver(event: PointerEvent): void {
  const slot = findPaperDollSlot(event.target);

  if (slot) {
    applyTooltip(slot);
  }
}

function handleDragStart(): void {
  dragInProgress = true;
  clearManagedTooltips();
  hideSlotTooltipsDuringDrag();
}

function handleDragEnd(): void {
  dragInProgress = false;
  restoreSlotTooltipsAfterDrag();
}

/**
 * Paper Doll gives empty slots an empty data-tooltip attribute. Add a WFRP4e
 * label just before Foundry handles the pointer event. Occupied slots include
 * their item name, and every WFRP4e label is suppressed while an item is dragged.
 */
export function registerPaperDollSlotTooltips(): void {
  document.addEventListener("pointerover", handlePointerOver, true);
  document.addEventListener("dragstart", handleDragStart, true);
  document.addEventListener("dragend", handleDragEnd, true);
}
