import { repairMadPrefabExclusions } from "./repair-mad-prefab-exclusions";
import { isModuleActive } from "../is-module-active";

export function registerScenePackerIntegration(): void {
  if (!isModuleActive("scene-packer")) return;
  if (game?.system.id !== "wfrp4e") return;

  // Scene Packer publishes this API at script load. Patch at init, before its
  // ready hook calls the content modules' scenePackerReady callbacks.
  if (typeof ScenePacker !== "undefined") repairMadPrefabExclusions(ScenePacker);
}
