import { MODULE_ID } from "../../constants";

interface CompatibilityPrompt {
  ignoreSetting: string;
  isEnabled: () => boolean;
  matches: () => boolean;
  title: () => string;
  content: () => string;
  configure: () => Promise<unknown>;
}

let queue: Promise<void> = Promise.resolve();
const pending = new Map<string, Promise<void>>();

export function registerCompatibilityPromptSetting(key: string, localizationRoot: string): void {
  // User roles are available at setup. Register on every client, showing the control only to GMs.
  Hooks.once("setup", () => {
    game?.settings.register(MODULE_ID, key, {
      name: `${localizationRoot}.IgnorePrompt.Name`,
      hint: `${localizationRoot}.IgnorePrompt.Hint`,
      config: game.user?.isGM === true,
      default: false,
      scope: "world",
      type: Boolean,
    });
  });
}

async function showPrompt(prompt: CompatibilityPrompt): Promise<void> {
  if (!game?.ready || game.system.id !== "wfrp4e" || !game.user?.isGM) return;
  if (game.users?.activeGM && game.users.activeGM.id !== game.user.id) return;
  if (!prompt.isEnabled() || game.settings.get(MODULE_ID, prompt.ignoreSetting) === true) return;
  if (prompt.matches()) return;

  const localize = (key: string): string =>
    game?.i18n.localize(`${MODULE_ID}.Settings.CompatibilityPrompts.${key}`) ?? key;
  const choice = await foundry.applications.api.DialogV2.wait({
    window: { title: prompt.title() },
    position: { width: 600 },
    content: `${prompt.content()}<p>${localize("Dismissal")}</p>`,
    buttons: [
      { action: "configure", label: localize("Configure"), default: true },
      { action: "keep", label: localize("Ignore") },
      { action: "later", label: localize("Later") },
    ],
    rejectClose: false,
  });
  if (choice === "configure") await prompt.configure();
  else if (choice === "keep") await game.settings.set(MODULE_ID, prompt.ignoreSetting, true);
}

export function promptCompatibilitySetup(prompt: CompatibilityPrompt): Promise<void> {
  const existing = pending.get(prompt.ignoreSetting);
  if (existing) return existing;
  // Recheck settings when each dialog reaches the front; never stack startup dialogs.
  const result = queue
    .then(() => showPrompt(prompt))
    .finally(() => {
      pending.delete(prompt.ignoreSetting);
    });
  pending.set(prompt.ignoreSetting, result);
  // A failed integration must not prevent the remaining startup checks.
  queue = result.catch(() => {});
  return result;
}
