interface BossBarStyle {
  id: string;
  type: number;
  background: string;
  bar: string;
  foreground: string;
  barHeight: number;
  tempBarColor: string;
  tempBarAlpha: number;
}

export function createWoundsBar(document: Document, style: BossBarStyle): HTMLElement {
  const container = document.createElement("div");
  container.className = `boss-bar-container ${style.type === 1 ? "matching-images" : "classic"} wfrp-bossbar-wounds`;
  container.style.setProperty("--bar-height", `${Math.max(4, style.barHeight * 0.3)}px`);
  container.style.setProperty("--bar-temp-color", style.tempBarColor);
  container.style.setProperty("--bar-temp-alpha", String(style.tempBarAlpha));
  for (const [layer, asset] of [
    ["background", style.background],
    ["bar", style.bar],
    ["foreground", style.foreground],
  ] as const) {
    const component = document.createElement("div");
    component.className = `bar-component bar-${layer}`;
    if (style.type === 1) {
      if (asset) {
        const image = document.createElement("img");
        image.src = asset;
        image.alt = "";
        component.append(image);
      }
    } else {
      const target = layer === "bar" ? document.createElement("div") : component;
      if (target !== component) {
        target.className = "inner";
        component.append(target);
      }
      target.style.backgroundImage = asset ? `url(${JSON.stringify(asset)})` : "none";
    }
    container.append(component);
  }
  return container;
}

export function getWoundsStyle(styles: BossBarStyle[], id: unknown): BossBarStyle | undefined {
  return styles.find((style) => style.id === id) ?? styles[0];
}
