import type { WfrpDataModelClass, WfrpMigrationData } from "../../../../types/wfrp/WfrpConfig";

const repairedDataModels = new WeakSet<WfrpDataModelClass>();

function repairDataModelMigration(dataModel: WfrpDataModelClass): boolean {
  const originalMigration = dataModel.migrateData;

  if (typeof originalMigration !== "function" || repairedDataModels.has(dataModel)) {
    return false;
  }

  dataModel.migrateData = function repairedMigration(
    this: WfrpDataModelClass,
    source: WfrpMigrationData,
  ): WfrpMigrationData {
    const migratedSource = originalMigration.call(this, source);
    return migratedSource === undefined ? source : migratedSource;
  };
  repairedDataModels.add(dataModel);
  return true;
}

export function repairWfrpDataModelMigrations(): number {
  const dataModels = [
    ...Object.values(CONFIG.Actor.dataModels),
    ...Object.values(CONFIG.Item.dataModels),
  ];

  return dataModels.reduce(
    (repairCount, dataModel) => repairCount + Number(repairDataModelMigration(dataModel)),
    0,
  );
}
