import { MODULE_ID } from "../../../constants";
import { promptCompatibilitySetup } from "../../settings/compatibility-prompts";
import { notifyError } from "../../notifications/notify-user";
import { isModuleActive } from "../is-module-active";
import { configureSplatter, matchesSplatterConfiguration } from "./configure-splatter";
import { SPLATTER_IGNORE_PROMPT_SETTING, SPLATTER_MODULE_ID } from "./constants";

const LOCALIZATION_ROOT = `${MODULE_ID}.Splatter.Configuration`;

function localize(key: string): string {
  return game?.i18n.localize(`${LOCALIZATION_ROOT}.${key}`) ?? key;
}

export function reportSplatterSetupError(error: unknown): void {
  notifyError(localize("Error"), error);
}

export function promptSplatterSetup(): Promise<void> {
  return promptCompatibilitySetup({
    ignoreSetting: SPLATTER_IGNORE_PROMPT_SETTING,
    isEnabled: () => isModuleActive(SPLATTER_MODULE_ID),
    matches: matchesSplatterConfiguration,
    title: () => localize("SetupTitle"),
    content: () => `<p>${localize("SetupDescription")}</p><p>${localize("Hint")}</p>`,
    configure: async () => {
      await configureSplatter();
      ui?.notifications?.info(localize("Success"));
    },
  });
}
